package com.example;

import org.eclipse.jdt.internal.ui.search.JavaElementLine;

// Minimal definition of JavaElementLine (before rename) to make MyConsumer compile
package org.eclipse.jdt.internal.ui.search;
public class JavaElementLine {
    private int fLineNumber;
    public JavaElementLine(Object element, int lineNumber, int lineStartOffset) { this.fLineNumber = lineNumber; }
    public int getLine() { return fLineNumber; }
}

package com.example;

class AnotherClass {
    public int getLine() { return 10; }
}

class MyConsumer {
    void process(JavaElementLine line) {
        int l1 = line.getLine(); // This call will be transformed by the rule
        System.out.println(l1);
    }
    void processAnother(AnotherClass another) {
        int l2 = another.getLine(); // This call must NOT be transformed (different type)
        System.out.println(l2);
    }
}
